from functools import lru_cache
class Solution:
    def longestString(self, x: int, y: int, z: int) -> int:
        @lru_cache(None)
        def f(a, b, c, last):
            best = 0
            if a and last != 'A': best = max(best, 1 + f(a - 1, b, c, 'A'))
            if b and last != 'B': best = max(best, 1 + f(a, b - 1, c, 'B'))
            if c: best = max(best, 1 + f(a, b, c - 1, 'B'))
            return best
        return 2 * f(x, y, z, '')

