class Solution {
    int memo[52][52][52][3];
    int f(int a, int b, int c, int last) {
        if (!a && !b && !c) return 0;
        int& r = memo[a][b][c][last];
        if (r != -1) return r;
        r = 0;
        if (a && last != 1) r = max(r, 1 + f(a - 1, b, c, 1));
        if (b && last != 2) r = max(r, 1 + f(a, b - 1, c, 2));
        if (c) r = max(r, 1 + f(a, b, c - 1, 2));
        return r;
    }
public:
    int longestString(int x, int y, int z) {
        memset(memo, -1, sizeof(memo));
        return 2 * f(x, y, z, 0);
    }
};

