class Solution {
    Integer[][][][] memo;
    int f(int a, int b, int c, int last) {
        if (a == 0 && b == 0 && c == 0) return 0;
        if (memo[a][b][c][last] != null) return memo[a][b][c][last];
        int best = 0;
        if (a > 0 && last != 1) best = Math.max(best, 1 + f(a - 1, b, c, 1));
        if (b > 0 && last != 2) best = Math.max(best, 1 + f(a, b - 1, c, 2));
        if (c > 0) best = Math.max(best, 1 + f(a, b, c - 1, 2));
        return memo[a][b][c][last] = best;
    }
    public int longestString(int x, int y, int z) {
        memo = new Integer[x + 1][y + 1][z + 1][3];
        return 2 * f(x, y, z, 0);
    }
}

