var longestString = function(x, y, z) {
    const memo = {};
    const f = (a, b, c, last) => {
        if (!a && !b && !c) return 0;
        const key = a + ',' + b + ',' + c + ',' + last;
        if (key in memo) return memo[key];
        let best = 0;
        if (a && last !== 1) best = Math.max(best, 1 + f(a - 1, b, c, 1));
        if (b && last !== 2) best = Math.max(best, 1 + f(a, b - 1, c, 2));
        if (c) best = Math.max(best, 1 + f(a, b, c - 1, 2));
        return memo[key] = best;
    };
    return 2 * f(x, y, z, 0);
};
